class Solution {
    public int minDailyLimit(int[] pages, int days) {
        int limit = 0;
        for (int p : pages) limit = Math.max(limit, p);
        while (daysNeeded(pages, limit) > days) limit++;
        return limit;
    }

    private int daysNeeded(int[] pages, int limit) {
        int used = 1, load = 0;
        for (int p : pages) {
            if (load + p > limit) { used++; load = 0; }
            load += p;
        }
        return used;
    }
}

